      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 10, discountPercent: 5 }],
    });

    const issuedResult = issueInvoice(invoiceResult.value, []);

    const invoice = {
      ...issuedResult.value,
      dueDate: '2025-02-14',
      payments: [{ amount: 5000 }],
      voucher: { code: 'WELCOME', amount: 1000 },
    };

    const text = renderInvoiceText(invoice);
    const lines = text.split('\n');

    // Verify structure
    assert(lines[0].includes('INV-'));
    assert(lines[1].includes(customers[0].name));
    assert(lines[2].includes('10x'));
    assert(lines[2].includes('5% off'));

    // Find lines for voucher, due date, and paid
    const hasVoucher = text.includes('Voucher (WELCOME)');
    const hasDue = text.includes('Due: 2025-02-14');
    const hasPaid = text.includes('Paid: €50.00');

    assert(hasVoucher);
    assert(hasDue);
    assert(hasPaid);
