  it('sums multiple payments in paid line', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const invoice = {
      ...invoiceResult.value,
      payments: [{ amount: 1000 }, { amount: 500 }, { amount: 750 }],
    };

    const text = renderInvoiceText(invoice);

    assert(text.includes('Paid: €22.50'));
  });

  it('does not show paid amount when no payments', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const text = renderInvoiceText(invoiceResult.value);

    assert(!text.includes('Paid:'));
  });

  it('shows all enhancements together', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 10, discountPercent: 5 }],
