import { describe, it } from 'node:test';
import { strict as assert } from 'node:assert';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { listCustomers } from '../src/customers.js';
import { listProducts } from '../src/catalogue.js';

describe('renderInvoiceText', () => {
  it('renders a draft invoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const text = renderInvoiceText(invoiceResult.value);
    const lines = text.split('\n');

    assert.equal(lines[0], 'DRAFT');
    assert.equal(lines[1], customers[0].name);
  });

  it('renders an issued invoice with number', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const issuedResult = issueInvoice(invoiceResult.value, []);
    const text = renderInvoiceText(issuedResult.value);
    const lines = text.split('\n');

    assert.equal(lines[0], 'INV-2025-0001');
  });

  it('includes customer name on second line', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const text = renderInvoiceText(invoiceResult.value);
    const lines = text.split('\n');

    assert.equal(lines[1], customers[0].name);
  });

  it('renders a single line item', () => {
    const products = listProducts();
    const customers = listCustomers();
    const product = products[0];
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: product.sku, qty: 3 }],
    });

    const text = renderInvoiceText(invoiceResult.value);
    const lines = text.split('\n');

    // Line format: qty x name @ €unitPrice = €total
    assert(lines[2].includes(`3x ${product.name} @`));
    assert(lines[2].includes('='));
  });

  it('renders multiple line items', () => {
    const products = listProducts();
    const customers = listCustomers();
    const standardCustomer = customers.find((c) => c.tier === 'standard');
    const invoiceResult = createInvoice({
      customerId: standardCustomer.id,
      issueDate: '2025-01-15',
      lines: [
        { sku: products[0].sku, qty: 2 },
        { sku: products[1].sku, qty: 3 },
      ],
    });

    const text = renderInvoiceText(invoiceResult.value);
    const lines = text.split('\n');

    // DRAFT + name + 2 items + Subtotal + VAT + Total
    assert.equal(lines.length, 7);
    assert(lines[2].includes(`2x ${products[0].name}`));
    assert(lines[3].includes(`3x ${products[1].name}`));
    assert(lines[4].includes('Subtotal:'));
    assert(lines[5].includes('VAT:'));
    assert(lines[6].includes('Total:'));
  });

  it('formats amounts as euros', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const text = renderInvoiceText(invoiceResult.value);

    assert(text.includes('€'));
  });

  it('includes total line at the end', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const text = renderInvoiceText(invoiceResult.value);
    const lines = text.split('\n');

    assert(lines[lines.length - 1].startsWith('Total:'));
  });

  it('calculates correct total for multiple items', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [
        { sku: products[0].sku, qty: 2 },
        { sku: products[1].sku, qty: 1 },
      ],
    });

    const text = renderInvoiceText(invoiceResult.value);
    const lines = text.split('\n');
    const totalLine = lines[lines.length - 1];

    // Total line should have two € signs (total prefix and amount)
    assert.equal((totalLine.match(/€/g) || []).length, 1);
    assert(totalLine.startsWith('Total: €'));
  });

  it('shows DRAFT for invoices without a number', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    assert.equal(invoiceResult.value.number, undefined);

    const text = renderInvoiceText(invoiceResult.value);
    const lines = text.split('\n');

    assert.equal(lines[0], 'DRAFT');
  });

  it('shows invoice number when present', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-06-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const issuedResult = issueInvoice(invoiceResult.value, ['INV-2025-0001']);
    const text = renderInvoiceText(issuedResult.value);
    const lines = text.split('\n');

    assert.equal(lines[0], 'INV-2025-0002');
  });

  it('renders with different customers', () => {
    const products = listProducts();
    const customers = listCustomers();

    for (let i = 0; i < Math.min(2, customers.length); i++) {
      const invoiceResult = createInvoice({
        customerId: customers[i].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
      });

      const text = renderInvoiceText(invoiceResult.value);
      const lines = text.split('\n');

      assert.equal(lines[1], customers[i].name);
    }
  });

  it('renders correctly with large quantities', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1000 }],
    });

    const text = renderInvoiceText(invoiceResult.value);

    assert(text.includes('1000x'));
  });

  it('handles zero-padded invoice numbers', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const issuedResult = issueInvoice(invoiceResult.value, []);
    const text = renderInvoiceText(issuedResult.value);
    const lines = text.split('\n');

    // First issued invoice should be 0001 with leading zeros
    assert.equal(lines[0], 'INV-2025-0001');
  });

  it('renders an invoice with all properties', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-03-20',
      lines: [
        { sku: products[0].sku, qty: 5 },
        { sku: products[1].sku, qty: 3 },
      ],
    });

    const issuedResult = issueInvoice(invoiceResult.value, []);
    const text = renderInvoiceText(issuedResult.value);

    // Verify structure: number, customer, lines, total
    assert(text.includes('INV-'));
    assert(text.includes(customers[0].name));
    assert(text.includes('5x'));
    assert(text.includes('3x'));
    assert(text.includes('Total:'));
  });

  it('returns string with newlines', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const text = renderInvoiceText(invoiceResult.value);

    assert.equal(typeof text, 'string');
    assert(text.includes('\n'));
  });

  it('formats line items with consistent format', () => {
    const products = listProducts();
    const customers = listCustomers();
    const standardCustomer = customers.find(c => c.tier === 'standard');
    const invoiceResult = createInvoice({
      customerId: standardCustomer.id,
      issueDate: '2025-01-15',
      lines: [
        { sku: products[0].sku, qty: 2 },
        { sku: products[1].sku, qty: 3 },
      ],
    });

    const text = renderInvoiceText(invoiceResult.value);
    const lines = text.split('\n');

    // Each line item should follow pattern: qty x name @ price = total (optionally with discount)
    const lineItem1 = lines[2];
    const lineItem2 = lines[3];

    assert(lineItem1.match(/^\d+x .* @ €[\d,.]+ = €[\d,.]+(\s*\(.+\))?$/));
    assert(lineItem2.match(/^\d+x .* @ €[\d,.]+ = €[\d,.]+(\s*\(.+\))?$/));
  });

  it('shows line discount when present', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 10, discountPercent: 10 }],
    });

    const text = renderInvoiceText(invoiceResult.value);

    assert(text.includes('10% off'));
    assert(text.includes('-€'));
  });

  it('shows line discount with discount percent', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 5, discountPercent: 15 }],
    });

    const text = renderInvoiceText(invoiceResult.value);

    assert(text.includes('15% off'));
  });

  it('does not show line discount for standard tier customer', () => {
    const products = listProducts();
    const customers = listCustomers();
    const standardCustomer = customers.find(c => c.tier === 'standard');
    const invoiceResult = createInvoice({
      customerId: standardCustomer.id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const text = renderInvoiceText(invoiceResult.value);

    // Standard tier has 0% discount, so no discount should be shown on the line
    assert(!text.includes('% off:'));
  });

  it('shows voucher before total', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const invoice = {
      ...invoiceResult.value,
      voucher: { code: 'SAVE10', amount: 500 },
    };

    const text = renderInvoiceText(invoice);

    assert(text.includes('Voucher (SAVE10)'));
    assert(text.includes('-€5.00'));
  });

  it('includes voucher code in output', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const invoice = {
      ...invoiceResult.value,
      voucher: { code: 'BLACKFRIDAY', amount: 1000 },
    };

    const text = renderInvoiceText(invoice);

    assert(text.includes('BLACKFRIDAY'));
  });

  it('shows due date when present', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const invoice = {
      ...invoiceResult.value,
      dueDate: '2025-02-14',
    };

    const text = renderInvoiceText(invoice);

    assert(text.includes('Due: 2025-02-14'));
  });

  it('shows due date from createInvoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const text = renderInvoiceText(invoiceResult.value);

    assert(text.includes('Due:'));
    assert(text.includes(invoiceResult.value.dueDate));
  });

  it('shows paid amount when payments present', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const invoice = {
      ...invoiceResult.value,
      payments: [{ amount: 2500 }, { amount: 1500 }],
    };

    const text = renderInvoiceText(invoice);

    assert(text.includes('Paid: €40.00'));
  });

  it('sums multiple payments in paid line', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const invoice = {
      ...invoiceResult.value,
      payments: [{ amount: 1000 }, { amount: 500 }, { amount: 750 }],
    };

    const text = renderInvoiceText(invoice);

    assert(text.includes('Paid: €22.50'));
  });

  it('does not show paid amount when no payments', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const text = renderInvoiceText(invoiceResult.value);

    assert(!text.includes('Paid:'));
  });

  it('shows all enhancements together', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 10, discountPercent: 5 }],
    });

    const issuedResult = issueInvoice(invoiceResult.value, []);

    const invoice = {
      ...issuedResult.value,
      dueDate: '2025-02-14',
      payments: [{ amount: 5000 }],
      voucher: { code: 'WELCOME', amount: 1000 },
    };

    const text = renderInvoiceText(invoice);
    const lines = text.split('\n');

    // Verify structure
    assert(lines[0].includes('INV-'));
    assert(lines[1].includes(customers[0].name));
    assert(lines[2].includes('10x'));
    assert(lines[2].includes('5% off'));

    // Find lines for voucher, due date, and paid
    const hasVoucher = text.includes('Voucher (WELCOME)');
    const hasDue = text.includes('Due: 2025-02-14');
    const hasPaid = text.includes('Paid: €50.00');

    assert(hasVoucher);
    assert(hasDue);
    assert(hasPaid);
  });

  it('places voucher before total', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const invoice = {
      ...invoiceResult.value,
      voucher: { code: 'TEST', amount: 500 },
    };

    const text = renderInvoiceText(invoice);
    const lines = text.split('\n');

    const voucherIndex = lines.findIndex(l => l.includes('Voucher'));
    const totalIndex = lines.findIndex(l => l.includes('Total:'));

    assert(voucherIndex < totalIndex);
    assert(voucherIndex > -1);
    assert(totalIndex > -1);
  });

  it('places due and paid after total', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const invoice = {
      ...invoiceResult.value,
      dueDate: '2025-02-14',
      payments: [{ amount: 1000 }],
    };

    const text = renderInvoiceText(invoice);
    const lines = text.split('\n');

    const totalIndex = lines.findIndex(l => l.includes('Total:'));
    const dueIndex = lines.findIndex(l => l.includes('Due:'));
    const paidIndex = lines.findIndex(l => l.includes('Paid:'));

    assert(totalIndex < dueIndex);
    assert(dueIndex < paidIndex);
  });
});

